from lib import *
LES = [
L("pow", "A", "Power rule and linearity", "กฎเลขยกกำลังและความเป็นเชิงเส้น",
 [T("<b>Lemma.</b> If $G'(x)=0$ for every $x$ in an interval $I$, then $G$ is constant on $I$.",
    "<b>บทตั้ง</b> ถ้า $G'(x)=0$ สำหรับทุก $x$ ในช่วง $I$ แล้ว $G$ เป็นค่าคงตัวบน $I$"),
  T("<b>Theorem (power rule).</b> Let $n\\neq-1$ be real and let $I$ be an interval on which $x^{n}$ is differentiable. Then the antiderivatives of $x^{n}$ on $I$ are exactly $$\\int x^{n}\\,dx=\\frac{x^{n+1}}{n+1}+C,\\qquad C\\in\\mathbb{R}.$$",
    "<b>ทฤษฎีบท (กฎเลขยกกำลัง)</b> ให้ $n\\neq-1$ เป็นจำนวนจริง และ $I$ เป็นช่วงที่ $x^{n}$ หาอนุพันธ์ได้ แล้วปฏิยานุพันธ์ทั้งหมดของ $x^{n}$ บน $I$ คือ $$\\int x^{n}\\,dx=\\frac{x^{n+1}}{n+1}+C,\\qquad C\\in\\mathbb{R}$$"),
  T("<b>Theorem (linearity).</b> If $F'=f$ and $G'=g$ on $I$, and $a,b\\in\\mathbb{R}$, then $$\\int\\big(af+bg\\big)\\,dx=a\\int f\\,dx+b\\int g\\,dx.$$",
    "<b>ทฤษฎีบท (ความเป็นเชิงเส้น)</b> ถ้า $F'=f$ และ $G'=g$ บน $I$ และ $a,b\\in\\mathbb{R}$ แล้ว $$\\int\\big(af+bg\\big)\\,dx=a\\int f\\,dx+b\\int g\\,dx$$"),
  T("The interval matters: on $\\mathbb{R}\\setminus\\{0\\}$ the constant may be different on each side of $0$.",
    "ช่วงมีความสำคัญ: บน $\\mathbb{R}\\setminus\\{0\\}$ ค่าคงตัวทางซ้ายและขวาของ $0$ อาจต่างกันได้")],
 [S("Proof of the lemma. Take any $x<y$ in $I$. $G$ is differentiable on $[x,y]$, so the mean value theorem gives a $c\\in(x,y)$ with",
    "พิสูจน์บทตั้ง ให้ $x<y$ ใด ๆ ใน $I$ เนื่องจาก $G$ หาอนุพันธ์ได้บน $[x,y]$ ทฤษฎีบทค่าเฉลี่ยให้ $c\\in(x,y)$ ที่",
    "G(y)-G(x)=G'(c)\\,(y-x)=0\\cdot(y-x)=0."),
  S("So $G(x)=G(y)$ for all $x,y\\in I$: $G$ is constant.", "ดังนั้น $G(x)=G(y)$ ทุก $x,y\\in I$ นั่นคือ $G$ เป็นค่าคงตัว"),
  S("Power rule. Since $n+1\\neq0$, the derivative power rule gives, for every $x\\in I$,", "กฎเลขยกกำลัง เนื่องจาก $n+1\\neq0$ กฎการหาอนุพันธ์ให้ว่าทุก $x\\in I$",
    "\\frac{d}{dx}\\left(\\frac{x^{n+1}}{n+1}\\right)=\\frac{(n+1)x^{n}}{n+1}=x^{n}."),
  S("So $\\dfrac{x^{n+1}}{n+1}+C$ is an antiderivative. Conversely, let $H$ be any antiderivative of $x^{n}$ on $I$. Then", "ดังนั้น $\\dfrac{x^{n+1}}{n+1}+C$ เป็นปฏิยานุพันธ์ ในทางกลับกัน ให้ $H$ เป็นปฏิยานุพันธ์ใด ๆ ของ $x^{n}$ บน $I$ จะได้",
    "\\left(H(x)-\\frac{x^{n+1}}{n+1}\\right)'=x^{n}-x^{n}=0,"),
  S("and by the lemma $H(x)-\\dfrac{x^{n+1}}{n+1}$ is a constant $C$. This is every antiderivative.", "และจากบทตั้ง $H(x)-\\dfrac{x^{n+1}}{n+1}$ เป็นค่าคงตัว $C$ จึงได้ปฏิยานุพันธ์ครบทุกตัว"),
  S("Linearity. Differentiation is linear, so", "ความเป็นเชิงเส้น การหาอนุพันธ์เป็นเชิงเส้น ดังนั้น",
    "(aF+bG)'=aF'+bG'=af+bg,"),
  S("so $aF+bG$ is an antiderivative of $af+bg$; by the lemma every other one differs from it by a constant. $\\blacksquare$", "ดังนั้น $aF+bG$ เป็นปฏิยานุพันธ์ของ $af+bg$ และจากบทตั้ง ตัวอื่นต่างจากนี้เพียงค่าคงตัว $\\blacksquare$")],
 [X(r"\int\left(4x^{3}-6x+2\right)dx", "x^4-3x^2+2x", r"x^{4}-3x^{2}+2x+C", "4*x**3-6*x+2", ("i", "0.5", "3"),
    [r"=4\cdot\frac{x^{4}}{4}-6\cdot\frac{x^{2}}{2}+2x+C", r"=x^{4}-3x^{2}+2x+C"]),
  X(r"\int_{1}^{4}\sqrt{x}\,(x+1)\,dx", "2/5*(32-1)+2/3*(8-1)", r"\frac{256}{15}", "sqrt(x)*(x+1)", ("d", "1", "4"),
    [r"\sqrt{x}(x+1)=x^{\frac32}+x^{\frac12}", r"\left[\tfrac25x^{\frac52}+\tfrac23x^{\frac32}\right]_{1}^{4}", r"=\tfrac25(32-1)+\tfrac23(8-1)=\frac{62}{5}+\frac{14}{3}=\frac{256}{15}"])],
 [P(r"\int\left(5x^{4}+3x^{2}\right)dx", "x^5+x^3", r"x^{5}+x^{3}+C", "5*x**4+3*x**2", ("i", "0.5", "2"), [r"5\cdot\frac{x^{5}}{5}+3\cdot\frac{x^{3}}{3}+C", r"=x^{5}+x^{3}+C"], "Use the power rule on each term.", "ใช้กฎเลขยกกำลังทีละพจน์"),
  P(r"\int_{1}^{2}\left(6x^{2}-4x\right)dx", "8", r"8", "6*x**2-4*x", ("d", "1", "2"), [r"\left[2x^{3}-2x^{2}\right]_{1}^{2}", r"=(16-8)-(2-2)=8"], "Antiderivative first, then $F(2)-F(1)$.", "หาปฏิยานุพันธ์ก่อน แล้วคำนวณ $F(2)-F(1)$"),
  P(r"\int_{1}^{4}\left(3\sqrt{x}-\frac{1}{x^{2}}\right)dx", "53/4", r"\frac{53}{4}", "3*sqrt(x)-1/x**2", ("d", "1", "4"), [r"\left[2x^{\frac32}+\frac1x\right]_{1}^{4}", r"=\left(16+\tfrac14\right)-(2+1)=\frac{53}{4}"], "Write $\\sqrt{x}=x^{1/2}$ and $\\frac{1}{x^{2}}=x^{-2}$.", "เขียน $\\sqrt{x}=x^{1/2}$ และ $\\frac{1}{x^{2}}=x^{-2}$"),
  P(r"\int\left(x^{2}+1\right)^{2}dx", "x^5/5+2x^3/3+x", r"\frac{x^{5}}{5}+\frac{2x^{3}}{3}+x+C", "(x**2+1)**2", ("i", "0.5", "2"), [r"\left(x^{2}+1\right)^{2}=x^{4}+2x^{2}+1", r"\frac{x^{5}}{5}+\frac{2x^{3}}{3}+x+C"], "Expand the bracket first.", "กระจายวงเล็บก่อน"),
  P(r"\int_{1}^{8}\left(x^{\frac13}+2\right)dx", "101/4", r"\frac{101}{4}", "cbrt(x)+2", ("d", "1", "8"), [r"\left[\tfrac34x^{\frac43}+2x\right]_{1}^{8}", r"=(12+16)-\left(\tfrac34+2\right)=\frac{101}{4}"], "$x^{4/3}$ at $x=8$ is $16$.", "$x^{4/3}$ ที่ $x=8$ เท่ากับ $16$")]),

L("exp", "A", "1/x and exponentials", "1/x และฟังก์ชันเลขชี้กำลัง",
 [T("<b>Theorem.</b> (i) On any interval not containing $0$, $$\\int\\frac{1}{x}\\,dx=\\ln|x|+C.$$ (ii) On $\\mathbb{R}$, $\\displaystyle\\int e^{x}\\,dx=e^{x}+C$, and for $a>0$, $a\\neq1$: $$\\int a^{x}\\,dx=\\frac{a^{x}}{\\ln a}+C.$$",
    "<b>ทฤษฎีบท</b> (i) บนช่วงใด ๆ ที่ไม่มี $0$ $$\\int\\frac{1}{x}\\,dx=\\ln|x|+C$$ (ii) บน $\\mathbb{R}$ $\\displaystyle\\int e^{x}\\,dx=e^{x}+C$ และสำหรับ $a>0$, $a\\neq1$: $$\\int a^{x}\\,dx=\\frac{a^{x}}{\\ln a}+C$$"),
  T("Warning: $\\displaystyle\\int_{-1}^{1}\\frac{dx}{x}$ does not exist, because $0$ is inside the interval and the improper integral diverges.",
    "ข้อควรระวัง: $\\displaystyle\\int_{-1}^{1}\\frac{dx}{x}$ ไม่มีค่า เพราะ $0$ อยู่ในช่วงและอินทิกรัลไม่ตรงแบบลู่ออก")],
 [S("For $x>0$: $\\ln|x|=\\ln x$ and", "เมื่อ $x>0$: $\\ln|x|=\\ln x$ และ", "\\frac{d}{dx}\\ln x=\\frac1x."),
  S("For $x<0$: $\\ln|x|=\\ln(-x)$, and by the chain rule", "เมื่อ $x<0$: $\\ln|x|=\\ln(-x)$ และจากกฎลูกโซ่", "\\frac{d}{dx}\\ln(-x)=\\frac{1}{-x}\\cdot(-1)=\\frac1x."),
  S("So $\\ln|x|$ is an antiderivative of $\\frac1x$ on any interval avoiding $0$; by the lemma of lesson 1 all others are $\\ln|x|+C$ on that interval.", "ดังนั้น $\\ln|x|$ เป็นปฏิยานุพันธ์ของ $\\frac1x$ บนช่วงที่ไม่มี $0$ และจากบทตั้งในบทที่ 1 ตัวอื่นทั้งหมดคือ $\\ln|x|+C$ บนช่วงนั้น"),
  S("$(e^{x})'=e^{x}$, which gives the second result. For $a^{x}$, write $a^{x}=e^{x\\ln a}$; by the chain rule", "$(e^{x})'=e^{x}$ ได้ผลข้อที่สอง สำหรับ $a^{x}$ เขียน $a^{x}=e^{x\\ln a}$ และจากกฎลูกโซ่", "\\frac{d}{dx}a^{x}=\\ln a\\cdot e^{x\\ln a}=a^{x}\\ln a."),
  S("Since $a\\neq1$, $\\ln a\\neq0$, so we may divide: $\\left(\\dfrac{a^{x}}{\\ln a}\\right)'=a^{x}$. $\\blacksquare$", "เนื่องจาก $a\\neq1$ จะได้ $\\ln a\\neq0$ จึงหารได้: $\\left(\\dfrac{a^{x}}{\\ln a}\\right)'=a^{x}$ $\\blacksquare$")],
 [X(r"\int_{-3}^{-1}\frac{1}{x}\,dx", "-ln(3)", r"-\ln3", "1/x", ("d", "-3", "-1"), [r"\text{The interval }[-3,-1]\text{ avoids }0", r"\left[\ln|x|\right]_{-3}^{-1}=\ln1-\ln3=-\ln3"]),
  X(r"\int2^{x}\,dx", "2^x/ln(2)", r"\frac{2^{x}}{\ln2}+C", "2**x", ("i", "0", "2"), [r"a=2:\ \int a^{x}dx=\frac{a^{x}}{\ln a}+C", r"=\frac{2^{x}}{\ln2}+C"])],
 [P(r"\int_{1}^{e^{2}}\frac{3}{x}\,dx", "6", r"6", "3/x", ("d", "1", "e**2"), [r"\left[3\ln x\right]_{1}^{e^{2}}=3\cdot2-0=6"], "$\\ln(e^{2})=2$.", "$\\ln(e^{2})=2$"),
  P(r"\int_{0}^{1}\left(e^{x}+1\right)dx", "e", r"e", "exp(x)+1", ("d", "0", "1"), [r"\left[e^{x}+x\right]_{0}^{1}=(e+1)-(1+0)=e"], "Integrate each term.", "อินทิเกรตทีละพจน์"),
  P(r"\int_{-e}^{-1}\frac{1}{x}\,dx", "-1", r"-1", "1/x", ("d", "-e", "-1"), [r"\left[\ln|x|\right]_{-e}^{-1}=\ln1-\ln e=-1"], "Use $\\ln|x|$: the interval is negative.", "ใช้ $\\ln|x|$ เพราะช่วงเป็นค่าลบ"),
  P(r"\int3^{x}\,dx", "3^x/ln(3)", r"\frac{3^{x}}{\ln3}+C", "3**x", ("i", "0", "2"), [r"\frac{3^{x}}{\ln3}+C"], "$\\int a^{x}dx=\\frac{a^{x}}{\\ln a}+C$.", "$\\int a^{x}dx=\\frac{a^{x}}{\\ln a}+C$"),
  P(r"\int_{1}^{2}\frac{(x+1)^{2}}{x}\,dx", "7/2+ln(2)", r"\frac72+\ln2", "(x+1)**2/x", ("d", "1", "2"), [r"\frac{(x+1)^{2}}{x}=x+2+\frac1x", r"\left[\tfrac{x^{2}}{2}+2x+\ln x\right]_{1}^{2}", r"=(2+4+\ln2)-\left(\tfrac12+2\right)=\frac72+\ln2"], "Expand, then divide each term by $x$.", "กระจายแล้วหารแต่ละพจน์ด้วย $x$")]),

L("trig", "A", "Standard trig integrals", "อินทิกรัลตรีโกณมาตรฐาน",
 [T("<b>Theorem.</b> On every interval where the integrand is defined: $$\\int\\sin x\\,dx=-\\cos x+C,\\quad \\int\\cos x\\,dx=\\sin x+C,$$ $$\\int\\sec^{2}x\\,dx=\\tan x+C,\\quad \\int\\csc^{2}x\\,dx=-\\cot x+C,$$ $$\\int\\sec x\\tan x\\,dx=\\sec x+C,\\quad \\int\\csc x\\cot x\\,dx=-\\csc x+C,$$ $$\\int\\tan x\\,dx=\\ln|\\sec x|+C,\\quad \\int\\sec x\\,dx=\\ln|\\sec x+\\tan x|+C.$$",
    "<b>ทฤษฎีบท</b> บนทุกช่วงที่ฟังก์ชันนิยาม: $$\\int\\sin x\\,dx=-\\cos x+C,\\quad \\int\\cos x\\,dx=\\sin x+C,$$ $$\\int\\sec^{2}x\\,dx=\\tan x+C,\\quad \\int\\csc^{2}x\\,dx=-\\cot x+C,$$ $$\\int\\sec x\\tan x\\,dx=\\sec x+C,\\quad \\int\\csc x\\cot x\\,dx=-\\csc x+C,$$ $$\\int\\tan x\\,dx=\\ln|\\sec x|+C,\\quad \\int\\sec x\\,dx=\\ln|\\sec x+\\tan x|+C$$"),
  T("We assume $(\\sin x)'=\\cos x$ and $(\\cos x)'=-\\sin x$ (these follow from $\\displaystyle\\lim_{h\\to0}\\frac{\\sin h}{h}=1$, with $x$ in radians).", "เราใช้ $(\\sin x)'=\\cos x$ และ $(\\cos x)'=-\\sin x$ (ได้จาก $\\displaystyle\\lim_{h\\to0}\\frac{\\sin h}{h}=1$ โดย $x$ เป็นเรเดียน)")],
 [S("Each line follows by differentiating the right-hand side. The first two are the assumed derivatives.", "แต่ละบรรทัดพิสูจน์ได้โดยหาอนุพันธ์ของด้านขวา สองบรรทัดแรกคืออนุพันธ์ที่สมมติไว้"),
  S("Quotient rule, where $\\cos x\\neq0$:", "กฎผลหาร เมื่อ $\\cos x\\neq0$:", "(\\tan x)'=\\left(\\frac{\\sin x}{\\cos x}\\right)'=\\frac{\\cos^{2}x+\\sin^{2}x}{\\cos^{2}x}=\\sec^{2}x,\\qquad (\\sec x)'=\\frac{\\sin x}{\\cos^{2}x}=\\sec x\\tan x."),
  S("The same with $\\sin x\\neq0$ gives $(\\cot x)'=-\\csc^{2}x$ and $(\\csc x)'=-\\csc x\\cot x$.", "ทำแบบเดียวกันเมื่อ $\\sin x\\neq0$ ได้ $(\\cot x)'=-\\csc^{2}x$ และ $(\\csc x)'=-\\csc x\\cot x$"),
  S("For $\\tan$: by the chain rule, $(\\ln|g|)'=g'/g$ wherever $g\\neq0$ (lesson 2). With $g=\\sec x$:", "สำหรับ $\\tan$: จากกฎลูกโซ่ $(\\ln|g|)'=g'/g$ เมื่อ $g\\neq0$ (บทที่ 2) ให้ $g=\\sec x$:", "(\\ln|\\sec x|)'=\\frac{\\sec x\\tan x}{\\sec x}=\\tan x."),
  S("For $\\sec$: with $g=\\sec x+\\tan x$ (where $g\\neq0$):", "สำหรับ $\\sec$: ให้ $g=\\sec x+\\tan x$ (เมื่อ $g\\neq0$):", "(\\ln|\\sec x+\\tan x|)'=\\frac{\\sec x\\tan x+\\sec^{2}x}{\\sec x+\\tan x}=\\frac{\\sec x(\\tan x+\\sec x)}{\\sec x+\\tan x}=\\sec x.\\ \\blacksquare")],
 [X(r"\int_{0}^{\frac{\pi}{3}}\sec x\tan x\,dx", "1", r"1", "sec(x)*tan(x)", ("d", "0", "pi/3"), [r"\left[\sec x\right]_{0}^{\frac{\pi}{3}}=2-1=1"]),
  X(r"\int\left(3\cos x-2\sec^{2}x\right)dx", "3sin(x)-2tan(x)", r"3\sin x-2\tan x+C", "3*cos(x)-2*sec(x)**2", ("i", "0.1", "1.2"), [r"3\sin x-2\tan x+C"])],
 [P(r"\int_{0}^{\frac{\pi}{2}}\left(\sin x+\cos x\right)dx", "2", r"2", "sin(x)+cos(x)", ("d", "0", "pi/2"), [r"\left[-\cos x+\sin x\right]_{0}^{\frac{\pi}{2}}=(0+1)-(-1+0)=2"], "$\\int\\sin=-\\cos$, $\\int\\cos=\\sin$.", "$\\int\\sin=-\\cos$, $\\int\\cos=\\sin$"),
  P(r"\int_{\frac{\pi}{6}}^{\frac{\pi}{2}}\csc^{2}x\,dx", "sqrt(3)", r"\sqrt3", "csc(x)**2", ("d", "pi/6", "pi/2"), [r"\left[-\cot x\right]_{\frac{\pi}{6}}^{\frac{\pi}{2}}=0-\left(-\sqrt3\right)=\sqrt3"], "$\\int\\csc^{2}x\\,dx=-\\cot x$.", "$\\int\\csc^{2}x\\,dx=-\\cot x$"),
  P(r"\int_{0}^{\frac{\pi}{4}}\tan x\,dx", "ln(2)/2", r"\frac{\ln2}{2}", "tan(x)", ("d", "0", "pi/4"), [r"\left[\ln|\sec x|\right]_{0}^{\frac{\pi}{4}}=\ln\sqrt2-\ln1=\frac{\ln2}{2}"], "$\\int\\tan x\\,dx=\\ln|\\sec x|$.", "$\\int\\tan x\\,dx=\\ln|\\sec x|$"),
  P(r"\int_{0}^{\frac{\pi}{4}}\sec x\,dx", "ln(1+sqrt(2))", r"\ln\left(1+\sqrt2\right)", "sec(x)", ("d", "0", "pi/4"), [r"\left[\ln|\sec x+\tan x|\right]_{0}^{\frac{\pi}{4}}=\ln\left(\sqrt2+1\right)-\ln1"], "$\\int\\sec x\\,dx=\\ln|\\sec x+\\tan x|$.", "$\\int\\sec x\\,dx=\\ln|\\sec x+\\tan x|$"),
  P(r"\int\left(2\cos x-\sec x\tan x\right)dx", "2sin(x)-sec(x)", r"2\sin x-\sec x+C", "2*cos(x)-sec(x)*tan(x)", ("i", "0.1", "1.2"), [r"2\sin x-\sec x+C"], "$\\int\\sec x\\tan x\\,dx=\\sec x$.", "$\\int\\sec x\\tan x\\,dx=\\sec x$")]),

L("ftc", "A", "The Fundamental Theorem of Calculus", "ทฤษฎีบทหลักมูลของแคลคูลัส",
 [T("<b>Theorem (FTC).</b> Let $f$ be continuous on $[a,b]$. <br>(1) The function $A(x)=\\displaystyle\\int_{a}^{x}f(t)\\,dt$ is differentiable on $(a,b)$ and $A'(x)=f(x)$. <br>(2) If $F$ is continuous on $[a,b]$ with $F'=f$ on $(a,b)$, then $$\\int_{a}^{b}f(x)\\,dx=F(b)-F(a).$$",
    "<b>ทฤษฎีบท (FTC)</b> ให้ $f$ ต่อเนื่องบน $[a,b]$ <br>(1) ฟังก์ชัน $A(x)=\\displaystyle\\int_{a}^{x}f(t)\\,dt$ หาอนุพันธ์ได้บน $(a,b)$ และ $A'(x)=f(x)$ <br>(2) ถ้า $F$ ต่อเนื่องบน $[a,b]$ และ $F'=f$ บน $(a,b)$ แล้ว $$\\int_{a}^{b}f(x)\\,dx=F(b)-F(a)$$"),
  T("If $f\\ge g$ on $[a,b]$, the area between the curves is $\\displaystyle\\int_{a}^{b}\\big(f(x)-g(x)\\big)\\,dx$.", "ถ้า $f\\ge g$ บน $[a,b]$ พื้นที่ระหว่างเส้นโค้งคือ $\\displaystyle\\int_{a}^{b}\\big(f(x)-g(x)\\big)\\,dx$")],
 [S("Mean value theorem for integrals. On $[x,x+h]$, $f$ is continuous, so by the extreme value theorem it has a minimum $m$ and maximum $M$; integrating $m\\le f\\le M$:", "ทฤษฎีบทค่าเฉลี่ยสำหรับอินทิกรัล บน $[x,x+h]$ $f$ ต่อเนื่อง จึงมีค่าต่ำสุด $m$ และสูงสุด $M$ (ทฤษฎีบทค่าสุดขีด) อินทิเกรต $m\\le f\\le M$:", "mh\\le\\int_{x}^{x+h}f(t)\\,dt\\le Mh."),
  S("By the intermediate value theorem, $f$ takes every value between $m$ and $M$, so there is $c_h\\in[x,x+h]$ with", "จากทฤษฎีบทค่าระหว่างกลาง $f$ มีทุกค่าระหว่าง $m$ และ $M$ จึงมี $c_h\\in[x,x+h]$ ที่", "\\int_{x}^{x+h}f(t)\\,dt=h\\,f(c_h)."),
  S("Part (1). By additivity of the integral, $A(x+h)-A(x)=\\int_{x}^{x+h}f$, so (the case $h<0$ is the same on $[x+h,x]$)", "ส่วน (1) จากสมบัติการบวกของอินทิกรัล $A(x+h)-A(x)=\\int_{x}^{x+h}f$ ดังนั้น (กรณี $h<0$ ทำบน $[x+h,x]$ เช่นเดียวกัน)", "\\frac{A(x+h)-A(x)}{h}=f(c_h)."),
  S("As $h\\to0$, $c_h\\to x$ (it is squeezed between $x$ and $x+h$), and $f$ is continuous, so $f(c_h)\\to f(x)$. Hence $A'(x)=f(x)$.", "เมื่อ $h\\to0$ จะได้ $c_h\\to x$ (ถูกบีบระหว่าง $x$ และ $x+h$) และ $f$ ต่อเนื่อง ดังนั้น $f(c_h)\\to f(x)$ จึงได้ $A'(x)=f(x)$"),
  S("Part (2). $F-A$ is continuous on $[a,b]$ with derivative $f-f=0$ on $(a,b)$. By the mean value theorem (as in lesson 1) it is constant, so", "ส่วน (2) $F-A$ ต่อเนื่องบน $[a,b]$ และมีอนุพันธ์ $f-f=0$ บน $(a,b)$ จากทฤษฎีบทค่าเฉลี่ย (เหมือนบทที่ 1) จึงเป็นค่าคงตัว ดังนั้น", "F(b)-A(b)=F(a)-A(a)=F(a)\\quad(\\text{since }A(a)=0)."),
  S("Therefore $\\displaystyle\\int_{a}^{b}f=A(b)=F(b)-F(a)$. $\\blacksquare$", "ดังนั้น $\\displaystyle\\int_{a}^{b}f=A(b)=F(b)-F(a)$ $\\blacksquare$")],
 [X(r"\text{Area between }y=x\text{ and }y=x^{2}\text{ for }0\le x\le1", "1/6", r"\frac16", "x-x**2", ("d", "0", "1"), [r"x\ge x^{2}\text{ on }[0,1]", r"\int_{0}^{1}\left(x-x^{2}\right)dx=\frac12-\frac13=\frac16"]),
  X(r"\int_{0}^{2}|x-1|\,dx", "1", r"1", "abs(x-1)", ("d", "0", "2", ["1"]), [r"\text{Split at }x=1:\ \int_{0}^{1}(1-x)\,dx+\int_{1}^{2}(x-1)\,dx", r"=\frac12+\frac12=1"])],
 [P(r"\int_{-2}^{2}\left(4-x^{2}\right)dx", "32/3", r"\frac{32}{3}", "4-x**2", ("d", "-2", "2"), [r"\left[4x-\tfrac{x^{3}}{3}\right]_{-2}^{2}=\left(8-\tfrac83\right)-\left(-8+\tfrac83\right)=\frac{32}{3}"], "$F(2)-F(-2)$ with $F(x)=4x-\\frac{x^{3}}{3}$.", "$F(2)-F(-2)$ โดย $F(x)=4x-\\frac{x^{3}}{3}$"),
  P(r"\int_{0}^{3}|x-2|\,dx", "5/2", r"\frac52", "abs(x-2)", ("d", "0", "3", ["2"]), [r"\int_{0}^{2}(2-x)\,dx+\int_{2}^{3}(x-2)\,dx", r"=2+\frac12=\frac52"], "Split where $x-2$ changes sign.", "แยกช่วงที่ $x-2$ เปลี่ยนเครื่องหมาย"),
  P(r"\text{Area between }y=x\text{ and }y=x^{3}\text{ for }0\le x\le1", "1/4", r"\frac14", "x-x**3", ("d", "0", "1"), [r"x\ge x^{3}\text{ on }[0,1]", r"\int_{0}^{1}\left(x-x^{3}\right)dx=\frac12-\frac14=\frac14"], "Top curve minus bottom curve.", "เส้นโค้งบนลบเส้นโค้งล่าง"),
  P(r"F(x)=\int_{0}^{x}\sqrt{1+t^{3}}\,dt.\ \text{Find }F'(2).", "3", r"3", "3", ("v", "3"), [r"\text{FTC part (1): }F'(x)=\sqrt{1+x^{3}}", r"F'(2)=\sqrt{9}=3"], "Part (1) of the FTC: no integrating needed.", "ใช้ FTC ส่วน (1) ไม่ต้องอินทิเกรต"),
  P(r"\int_{-1}^{2}\left(3x^{2}-2x\right)dx", "6", r"6", "3*x**2-2*x", ("d", "-1", "2"), [r"\left[x^{3}-x^{2}\right]_{-1}^{2}=(8-4)-(-1-1)=6"], "Careful with $(-1)^{3}$.", "ระวัง $(-1)^{3}$")]),
]
